CREATE TABLE public.bell_board_chat_pairs(interest_id uuid NOT NULL,member_id uuid NOT NULL REFERENCES public.profiles(id),owner_id uuid NOT NULL REFERENCES public.profiles(id),PRIMARY KEY(interest_id,member_id)); GRANT SELECT ON public.bell_board_chat_pairs TO authenticated; GRANT ALL ON public.bell_board_chat_pairs TO service_role; ALTER TABLE public.bell_board_chat_pairs ENABLE ROW LEVEL SECURITY; CREATE POLICY bell_board_participants ON public.bell_board_chat_pairs FOR SELECT TO authenticated USING(auth.uid() IN(member_id,owner_id));
CREATE OR REPLACE FUNCTION public.open_anonymous_bell_chat(_id uuid,_source text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) OR NOT public.has_paid_bell(auth.uid()) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; IF _source='vehicle' THEN RETURN public.open_vehicle_demand_chat(_id); ELSIF _source='post' THEN SELECT user_id INTO target FROM public.post_bell_interests WHERE id=_id; ELSIF _source='service' THEN SELECT user_id INTO target FROM public.service_requests WHERE id=_id; END IF; IF target IS NULL OR target=auth.uid() OR NOT public.account_allowed(target) THEN RAISE EXCEPTION 'DEMAND_UNAVAILABLE'; END IF; INSERT INTO public.bell_board_chat_pairs VALUES(_id,auth.uid(),target) ON CONFLICT DO NOTHING; RETURN target; END $$;
CREATE OR REPLACE FUNCTION public.can_post_chat(_post uuid DEFAULT NULL,_other uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND auth.uid()<>_other AND public.account_allowed(auth.uid()) AND public.account_allowed(_other) AND CASE WHEN _other=public.support_admin_id() OR public.has_role(auth.uid(),'admin') THEN true WHEN NOT public.has_paid_bell(auth.uid()) THEN false WHEN _post IS NULL THEN EXISTS(SELECT 1 FROM public.bell_board_chat_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.vehicle_demand_chat_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.service_request_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.service_chat_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.messages WHERE post_id IS NULL AND ((sender_id=auth.uid() AND receiver_id=_other) OR (receiver_id=auth.uid() AND sender_id=_other))) ELSE EXISTS(SELECT 1 FROM public.post_chat_pairs WHERE post_id=_post AND ((member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other))) END $$;
CREATE FUNCTION public.capture_service_response_bell() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.service_requests; BEGIN SELECT * INTO r FROM public.service_requests WHERE id=NEW.request_id; IF r.id IS NOT NULL THEN INSERT INTO public.post_bell_interests(user_id,post_id,section,area,need) VALUES(NEW.member_id,r.id,'service-wanted',r.area,r.service) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER capture_service_response_bell AFTER INSERT ON public.service_request_pairs FOR EACH ROW EXECUTE FUNCTION public.capture_service_response_bell();
INSERT INTO public.post_bell_interests(user_id,post_id,section,area,need) SELECT p.member_id,r.id,'service-wanted',r.area,r.service FROM public.service_request_pairs p JOIN public.service_requests r ON r.id=p.request_id ON CONFLICT DO NOTHING;